def parse_int(value: str, flag: str) -> int:
    try:
        return int(value, 10)
    except ValueError:
        raise OptionError(f'Value "{value}" not valid for option {flag}: invalid digit found in string')


def parse_sort(value: str) -> str:
    mapping = {
